class NotFoundError extends Error {
  readonly status = 404
  constructor(what: string, options?: ErrorOptions) {
    super(`${what} not found`, options)
    this.name = 'NotFoundError'
  }
}

try {
  await repo.get(id)
} catch (err) {
  throw new NotFoundError(`order ${id}`, { cause: err })
}

